using System;using System.Collections.Generic;using System.Globalization;using System.IO;using System.Linq;using System.Net.Http;using System.Runtime.Serialization;using System.Text;using System.Threading.Tasks;using System.Windows;using System.Windows.Automation;using System.Windows.Controls;using System.Windows.Controls.Primitives;using System.Windows.Input;using System.Windows.Media;using System.Windows.Media.Animation;using System.Windows.Media.Imaging;using System.Xml;using System.Xml.Linq;
namespace SeraphimLuxury {
 class NewsStory {public string Title,Url,Source,Date;}
 static class CountryNews {
  public static async Task<List<NewsStory>> Load(string place){using(var client=new HttpClient {Timeout=TimeSpan.FromSeconds(15)}){client.DefaultRequestHeaders.UserAgent.ParseAdd("Seraphim/0.12");string url="https://news.google.com/rss/search?q="+Uri.EscapeDataString(place)+"&hl=fr&gl=FR&ceid=FR:fr";string xml=await client.GetStringAsync(url);if(xml.Length>1500000)throw new IOException("Flux trop volumineux.");return Parse(xml);}}
  internal static List<NewsStory> Parse(string xml){using(var reader=XmlReader.Create(new StringReader(xml),new XmlReaderSettings {DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null})){var doc=XDocument.Load(reader);return doc.Descendants("item").Take(24).Select(i=>new NewsStory {Title=(string)i.Element("title")??"Actualité",Url=(string)i.Element("link"),Source=(string)i.Element("source")??"Google Actualités",Date=(string)i.Element("pubDate")??""}).Where(i=>{Uri uri;return Uri.TryCreate(i.Url,UriKind.Absolute,out uri)&&uri.Scheme=="https";}).ToList();}}
 }
