  internal static List<string> ParseBlacklist(string text){return text.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries).Select(t=>t.Trim()).Where(t=>t.Length>=2&&t.Length<=120).Distinct(StringComparer.OrdinalIgnoreCase).Take(500).ToList();}
